    /// THE ARMED HIT'S OWN PIN (the attribute pipeline the equipment
    /// walk speaks — the item's mainhand ATTACK_DAMAGE modifier ANY
    /// holder's attribute rides): the iron sword the 3.0 + 5.0 the
    /// hit deals (the sword's own base + the IRON tier's bonus — the
    /// same amounts the player's first-person lane walks), the iron
    /// axe the tool row's 8.0 modifier the 11.0 total deals, the
    /// non-weapon word the 0.0 addend the bare 3.0 keeps, the
    /// OFFHAND sword the mainhand slot the modifier tags to the bare
    /// floor keeps.
    #[test]
    fn the_armed_zombies_hit_the_weapons_own_bonus_deals() {
        let world = flat_world();
        // the arms-length pad: the melee range the first tick lands
        let land = |z: &mut Zombie| -> f64 {
            let player = player_at(z.x - 1.0, z.y, z.z);
            for _ in 0..40 {
                if let Some(atk) = z.tick(&world, Some(&player), NIGHT).attack {
                    return atk.damage;
                }
            }
            panic!("the melee hit never landed");
        };
        // the BARE hand the 3.0 floor keeps (the createAttributes' own
        // value — the same pin the chase test walks)
        let mut bare = Zombie::new(1, 8.0, 5.0, 8.0, 7);
        bare.on_ground = true;
        assert!((land(&mut bare) - 3.0).abs() < 1e-9, "the bare the floor keeps");
        // the IRON SWORD the 8.0 total deals (the modifier 5.0: the
        // sword's 3.0 base + the IRON tier's 2.0 bonus)
        let mut sword = Zombie::new(2, 8.0, 5.0, 8.0, 7);
        sword.on_ground = true;
        sword.held_weapon = Some("iron_sword");
        assert!(
            (land(&mut sword) - 8.0).abs() < 1e-9,
            "the iron sword the 3+5 the hit deals"
        );
        // the IRON AXE the tool row's own modifier deals (6.0 + 2.0 —
        // the 11.0 total the tool table's dmg_arg keeps)
        let mut axe = Zombie::new(3, 8.0, 5.0, 8.0, 7);
        axe.on_ground = true;
        axe.held_weapon = Some("iron_axe");
        assert!(
            (land(&mut axe) - 11.0).abs() < 1e-9,
            "the iron axe the 3+8 the hit deals"
        );
        // the NON-WEAPON word the honest bare keeps (the helmet the
        // attack table never rows — the 0.0 addend the 3.0 floor keeps)
        let mut helmeted = Zombie::new(4, 8.0, 5.0, 8.0, 7);
        helmeted.on_ground = true;
        helmeted.held_weapon = Some("iron_helmet");
        assert!(
            (land(&mut helmeted) - 3.0).abs() < 1e-9,
            "the non-weapon the bare keeps"
        );
        // the OFFHAND sword the modifier never rides (the MAINHAND slot
        // the attribute modifiers tag to — the left hand the damage
        // never arms)
        let mut lefty = Zombie::new(5, 8.0, 5.0, 8.0, 7);
        lefty.on_ground = true;
        lefty.held_offhand = Some("iron_sword");
        assert!(
            (land(&mut lefty) - 3.0).abs() < 1e-9,
            "the offhand the modifier never rides"
        );
    }

    /// THE FOOTSTEP CADENCE (Entity.move's own law over the walking
    /// zombie): the chase walk accumulates moveDist at the collided
    /// horizontal × 0.6, the step fires past nextStep (the ctor's own
    /// 1.0F) over solid ground, the count stays inside the whole-unit
    /// bound and the first step never speaks before the ctor's 1.0F.
    #[test]
    fn the_walking_zombie_speaks_the_footstep_cadence() {
        let world = flat_world();
        let mut z = Zombie::new(1, 8.0, 5.0, 8.0, 7);
        z.on_ground = true;
        let player = player_at(2.0, 5.0, 8.0); // 6 blocks west, on the pad — the walk crosses the ctor's 1.0F
        let mut steps = 0;
        let mut first_step_move_dist = None;
        for _ in 0..400 {
            let ev = z.tick(&world, Some(&player), NIGHT);
            if ev.step {
                steps += 1;
                if first_step_move_dist.is_none() {
                    first_step_move_dist = Some(z.move_dist);
                }
            }
            if ev.attack.is_some() {
                break;
            }
        }
        let md = z.move_dist;
        assert!(md > 1.0, "the walk accumulated the vanilla law ({md})");
        let first = first_step_move_dist.expect("the walk spoke at least one step");
        assert!(
            first > 1.0,
            "the ctor's own 1.0F gates the first step ({first})"
        );
        assert!(
            steps <= md as i32 as usize,
            "the cadence bound: {steps} steps for moveDist {md}"
        );
        // the reset rode nextStep(): the last threshold sits one whole
        // unit past the walked distance
        assert!(
            z.next_step > md - 1.0 && z.next_step <= md + 1.0,
            "the reset law: nextStep {} for moveDist {}",
            z.next_step,
            md
        );
    }

    /// THE AIRBORNE GATE (vibrationAndSoundEffectsFromBlock's own
    /// verdict): the hovered zombie's walk accumulates moveDist but the
    /// steps stay silent — the feet left the ground — and the landing
    /// speaks the whole accumulated crossing at once (the reset rides
    /// nextStep()).
    #[test]
    fn the_airborne_zombie_never_steps_until_the_landing() {
        let world = flat_world();
        let mut z = Zombie::new(1, 8.0, 5.0, 8.0, 7);
        z.on_ground = true;
        let player = player_at(2.0, 5.0, 8.0);
        let mut steps = 0;
        for _ in 0..25 {
            // the hover-leg: the jump impulse re-applied every tick —
            // the chase still drives the horizontal walk
            z.vy = crate::body::JUMP_POWER as f64;
            if z.tick(&world, Some(&player), NIGHT).step {
                steps += 1;
            }
        }
        assert!(
            z.move_dist > 1.0,
            "the air walk accumulated the law ({})",
            z.move_dist
        );
        assert_eq!(steps, 0, "the airborne gate holds the steps");
        // the landing: the feet touch, the whole crossing speaks
        for _ in 0..120 {
            if z.tick(&world, Some(&player), NIGHT).step {
                steps += 1;
            }
        }
        assert!(steps >= 1, "the landing fired the accumulated step");
    }

    /// THE STEP VOICE'S OWN SPLIT (javap the 26.2 jar's playStepSound
    /// pair): the zombie's own override the FLAT fold keeps — every
    /// surface (even the air the caller never passes) the same voice,
    /// no block state the fold reads; the farm animals' own overrides
    /// the 26.2 classfiles speak (Pig/Chicken/AbstractCow the
    /// `getSoundSet().stepSound()` walks keep — the flat 0.15F/1.0F
    /// pairs the classic sets' own step words name), the sheep the
    /// base's block law wears (no sound variant, no override the
    /// classfile keeps) — the grass pad (1.0, 1.0) the fold walks to
    /// block.grass.step at 0.15/1.0. The air and the unknown block
    /// the None keeps — the vanilla never hears them either.
    #[test]
    fn the_step_voice_splits_the_kinds_the_block_law_speaks() {
        // the zombie's flat override — two surfaces, one voice
        for under in [None, Some("grass_block"), Some("stone")] {
            assert_eq!(
                MobKind::Zombie.step_voice(under),
                Some(("entity.zombie.step", ZOMBIE_STEP_VOLUME, ZOMBIE_STEP_PITCH)),
                "the zombie's flat fold answers every surface"
            );
        }
        // THE FARM ANIMALS' OWN FLAT OVERRIDES (the 26.2 jar's own
        // classfiles — the set's step word the block state never
        // bends)
        assert_eq!(
            MobKind::Chicken.step_voice(Some("grass_block")),
            Some(("entity.chicken.step", 0.15, 1.0))
        );
        assert_eq!(
            MobKind::Pig.step_voice(Some("stone")),
            Some(("entity.pig.step", 0.15, 1.0))
        );
        assert_eq!(
            MobKind::Cow.step_voice(None),
            Some(("entity.cow.step", 0.15, 1.0)),
            "the flat fold answers the air too"
        );
        // THE SHEEP'S BLOCK LAW — the SoundType's own base the fold walks
        let (event, v, p) = MobKind::Sheep
            .step_voice(Some("grass_block"))
            .expect("the grass pad's voice");
        assert_eq!(event, "block.grass.step", "the grass pad's event");
        assert_eq!((v, p), (0.15, 1.0), "the grass base pair the fold walks");
        let (event, v, p) = MobKind::Sheep
            .step_voice(Some("stone"))
            .expect("the stone pad's voice");
        assert_eq!(event, "block.stone.step", "the stone pad's event");
        assert_eq!((v, p), (0.15, 1.0), "the stone base pair the fold walks");
        // the silent lanes the None keeps
        assert_eq!(MobKind::Sheep.step_voice(None), None, "the air never speaks");
        assert_eq!(
            MobKind::Sheep.step_voice(Some("not_a_block")),
            None,
            "the unknown block the table never names"
        );
    }

    /// THE SOUND VARIANTS' OWN TABLES (javap the 26.2 jar's own
    /// sound-variant jsons the data/ verbatim banks — the slots the
    /// class-tree walk lands, the sets the isBaby split keeps for the
    /// pig and the chicken, the cow's flat set the baby lane never
    /// splits, the step/eat rows the overrides speak).
    #[test]
    fn the_sound_variants_the_jar_jsons_speak() {
        // THE WIRE INDICES' OWN PINS (the clinit walks the 26.2 jar
        // speaks: the chicken's sound variant the 19th, the pig's the
        // 20th — the BOOST 18 + VARIANT 19 pair rides before it — the
        // cow's the 19th)
        assert_eq!(CHICKEN_DATA_SOUND_VARIANT_ID, 19);
        assert_eq!(PIG_DATA_SOUND_VARIANT_ID, 20);
        assert_eq!(COW_DATA_SOUND_VARIANT_ID, 19);

        // THE PIG'S OWN PAIR (pig_sound_variant/classic.json +
        // big.json — the big's ambient/hurt/death rows the pig_big
        // prefix speaks, the step rows BOTH sets' entity.pig.step
        // keeps, the baby rows the baby_pig prefix names)
        assert_eq!(
            farm_sound_variant_word(MobKind::Pig, "minecraft:classic", false, VoiceSlot::Ambient),
            Some("entity.pig.ambient")
        );
        assert_eq!(
            farm_sound_variant_word(MobKind::Pig, "minecraft:big", false, VoiceSlot::Ambient),
            Some("entity.pig_big.ambient")
        );
        assert_eq!(
            farm_sound_variant_word(MobKind::Pig, "minecraft:big", false, VoiceSlot::Hurt),
            Some("entity.pig_big.hurt")
        );
        assert_eq!(
            farm_sound_variant_word(MobKind::Pig, "minecraft:big", false, VoiceSlot::Death),
            Some("entity.pig_big.death")
        );
        assert_eq!(
            farm_sound_variant_word(MobKind::Pig, "minecraft:big", true, VoiceSlot::Ambient),
            Some("entity.baby_pig.ambient"),
            "the baby set the isBaby split keeps"
        );
        assert_eq!(
            farm_sound_variant_step(MobKind::Pig, "minecraft:big", false),
            Some("entity.pig.step"),
            "the step rows both sets' classic word keeps"
        );
        assert_eq!(
            farm_sound_variant_step(MobKind::Pig, "minecraft:big", true),
            Some("entity.baby_pig.step")
        );
        // THE PIG'S EAT ROWS (playEatingSound's own set read — the
        // big adult the pig_big row speaks, the baby the baby_pig row)
        assert_eq!(farm_sound_variant_eat("minecraft:classic", false), Some("entity.pig.eat"));
        assert_eq!(farm_sound_variant_eat("minecraft:big", false), Some("entity.pig_big.eat"));
        assert_eq!(farm_sound_variant_eat("minecraft:big", true), Some("entity.baby_pig.eat"));

        // THE CHICKEN'S OWN PAIR (chicken_sound_variant/classic.json
        // + picky.json — the picky's ambient/hurt/death rows the
        // chicken_picky prefix speaks, the step the both sets'
        // entity.chicken.step keeps, the baby the baby_chicken rows)
        assert_eq!(
            farm_sound_variant_word(
                MobKind::Chicken,
                "minecraft:picky",
                false,
                VoiceSlot::Ambient
            ),
            Some("entity.chicken_picky.ambient")
        );
        assert_eq!(
            farm_sound_variant_word(MobKind::Chicken, "minecraft:picky", false, VoiceSlot::Hurt),
            Some("entity.chicken_picky.hurt")
        );
        assert_eq!(
            farm_sound_variant_word(
                MobKind::Chicken,
                "minecraft:picky",
                true,
                VoiceSlot::Death
            ),
            Some("entity.baby_chicken.death")
        );
        assert_eq!(
            farm_sound_variant_step(MobKind::Chicken, "minecraft:picky", false),
            Some("entity.chicken.step")
        );

        // THE COW'S OWN PAIR (cow_sound_variant/classic.json +
        // moody.json — the FLAT set the json shape keeps, the moody
        // rows the cow_moody prefix speaks, the baby the split never
        // takes)
        assert_eq!(
            farm_sound_variant_word(MobKind::Cow, "minecraft:moody", true, VoiceSlot::Ambient),
            Some("entity.cow_moody.ambient"),
            "the flat set the baby split never bends"
        );
        assert_eq!(
            farm_sound_variant_word(MobKind::Cow, "minecraft:classic", false, VoiceSlot::Hurt),
            Some("entity.cow.hurt")
        );
        assert_eq!(
            farm_sound_variant_step(MobKind::Cow, "minecraft:moody", false),
            Some("entity.cow_moody.step")
        );

        // THE HONEST LANES THE SILENCE KEEPS (the unknown variant name,
        // the kind the sound slot never feeds, the sheep the no-variant
        // family keeps)
        assert_eq!(
            farm_sound_variant_word(MobKind::Pig, "minecraft:plains", false, VoiceSlot::Ambient),
            None
        );
        assert_eq!(
            farm_sound_variant_word(MobKind::Zombie, "minecraft:classic", false, VoiceSlot::Ambient),
            None
        );
        assert_eq!(farm_sound_variant_step(MobKind::Sheep, "minecraft:classic", false), None);
    }

    /// THE MOB'S OWN VOICE WORDS (javap the getters' walk the synced
    /// set feeds — the big pig's ambient/hurt/death rows the
    /// pig_big prefix speaks, the baby the baby_pig rows answer, the
    /// never-spoken slot the classic kind rows keep; the step the
    /// flat 0.15/1.0 pair the overrides play, the eat the pig's own
    /// lane keeps).
    #[test]
    fn the_mob_voice_words_the_synced_set_speaks() {
        let mut m = Zombie::new(1, 0.0, 64.0, 0.0, 7);
        m.kind = MobKind::Pig;
        // the never-spoken slot: the classic kind rows the honest
        // default keeps
        assert_eq!(m.voice_event(VoiceSlot::Ambient), "entity.pig.ambient");
        assert_eq!(m.step_voice(Some("stone")), Some(("entity.pig.step", 0.15, 1.0)));
        assert_eq!(m.eat_voice(), Some("entity.pig.eat"));
        // THE BIG SET'S OWN RIDE (the synced word the entity data
        // carries — the adult rows the pig_big prefix speaks, the eat
        // the set's own row wears)
        m.farm_sound_variant = Some("minecraft:big".to_string());
        assert_eq!(m.voice_event(VoiceSlot::Ambient), "entity.pig_big.ambient");
        assert_eq!(m.voice_event(VoiceSlot::Hurt), "entity.pig_big.hurt");
        assert_eq!(m.voice_event(VoiceSlot::Death), "entity.pig_big.death");
        assert_eq!(m.eat_voice(), Some("entity.pig_big.eat"));
        // THE BABY'S OWN SPLIT (the isBaby gate the getSoundSet walk
        // keeps — the baby rows both variants share)
        m.set_age(crate::mob::BABY_START_AGE);
        assert_eq!(m.voice_event(VoiceSlot::Ambient), "entity.baby_pig.ambient");
        assert_eq!(m.step_voice(None), Some(("entity.baby_pig.step", 0.15, 1.0)));
        assert_eq!(m.eat_voice(), Some("entity.baby_pig.eat"));
        // THE NON-PIG'S OWN SILENCE (the eat lane the pig only owns)
        let mut c = Zombie::new(2, 0.0, 64.0, 0.0, 8);
        c.kind = MobKind::Chicken;
        assert_eq!(c.eat_voice(), None);
        c.farm_sound_variant = Some("minecraft:picky".to_string());
        assert_eq!(c.voice_event(VoiceSlot::Ambient), "entity.chicken_picky.ambient");
        assert_eq!(c.step_voice(None), Some(("entity.chicken.step", 0.15, 1.0)));
        // the cow's flat set — the moody word the baby split never bends
        let mut cw = Zombie::new(3, 0.0, 64.0, 0.0, 9);
        cw.kind = MobKind::Cow;
        cw.farm_sound_variant = Some("minecraft:moody".to_string());
        cw.set_age(crate::mob::BABY_START_AGE);
        assert_eq!(cw.voice_event(VoiceSlot::Ambient), "entity.cow_moody.ambient");
        assert_eq!(cw.step_voice(Some("grass_block")), Some(("entity.cow_moody.step", 0.15, 1.0)));
        // THE SHEEP'S OWN KIND LANE (no sound variant the family
        // carries — the voice rows the kind's table keeps, the step
        // the block law walks)
        let mut s = Zombie::new(4, 0.0, 64.0, 0.0, 10);
        s.kind = MobKind::Sheep;
        s.farm_sound_variant = Some("minecraft:moody".to_string());
        assert_eq!(s.voice_event(VoiceSlot::Ambient), "entity.sheep.ambient");
        assert_eq!(
            s.step_voice(Some("grass_block")),
            Some(("block.grass.step", 0.15, 1.0))
        );
    }

    /// THE PICK's own slab test (javap `AABB.clip`): the ray through
    /// the box hits, the parallel axis folds honestly, the miss and
    /// the start-inside branch speak their verdicts.
    #[test]
    fn the_aabb_clip_hits_and_misses() {
        let min = (-0.3, 0.0, -0.3);
        let max = (0.3, 1.95, 0.3);
        // a ray through the box's middle, from 5 blocks out
        let hit = aabb_clip((-5.0, 1.0, 0.0), (5.0, 1.0, 0.0), min, max);
        let (p, t) = hit.expect("the ray enters");
        assert!((p.0 - (-0.3)).abs() < 1e-9, "entry x {}", p.0);
        assert!((t - 4.7 / 10.0).abs() < 1e-9, "t {t}");
        // the parallel view along the box's plane misses it
        assert!(aabb_clip((5.0, 1.0, 5.0), (5.0, 1.0, -5.0), min, max).is_none());
        // the start inside speaks t = 0 at the own position
        let inside = aabb_clip((0.0, 1.0, 0.0), (5.0, 1.0, 0.0), min, max);
        let (_, t) = inside.expect("inside");
        assert!(t.abs() < 1e-9, "inside t {t}");
    }

    /// THE CROSSHAIR'S PICK (ProjectileUtil's own verdict): the
    /// nearest box wins, the corpses never pick, the search sphere
    /// eats the far ring.
    #[test]
    fn the_pick_nearest_wins_and_corpses_never_pick() {
        let mut near = Zombie::new(1, 2.0, 0.0, 0.0, 7);
        let far = Zombie::new(2, 4.0, 0.0, 0.0, 7);
        near.y = 0.0;
        let mobs = vec![near, far];
        let eye = (0.0, 1.0, 0.0);
        let _view = (1.0, -0.2 / 2.0, 0.0); // level-out: the boxes at y 0..1.95
                                           // aim level at the bodies' middle (y 1.0 eye, the ray rides x)
        let view = (1.0, 0.0, 0.0);
        let picked = pick_entity(&mobs, eye, view, 4.5);
        assert_eq!(picked.unwrap().0, 0, "the nearer zombie wins");
        // the dead never pick: kill the near one, the far speaks
        let mut dead = Zombie::new(3, 2.0, 0.0, 0.0, 7);
        dead.health = 0.0;
        dead.death_time = 5;
        let mobs = vec![dead, Zombie::new(4, 4.0, 0.0, 0.0, 7)];
        let picked = pick_entity(&mobs, eye, view, 4.5);
        assert_eq!(picked.unwrap().0, 1, "the corpse never picks");
        // beyond the search sphere: nothing
        let mobs = vec![Zombie::new(5, 10.0, 0.0, 0.0, 7)];
        assert!(pick_entity(&mobs, eye, view, 4.5).is_none());
    }

    /// THE SPAWNER'S SURFACE LAW: the attempt lands on the topmost
    /// solid's head-room, inside the 24..48 ring, and the day gate
    /// refuses (night=false speaks nothing).
    #[test]
    fn the_spawner_lands_on_the_surface_with_head_room() {
        let mut world = World::new(4, 42);
        // the midnight clock the gate's stage 3 wears (the spawn law
        // the live lane answers — the world's own day_tick the app
        // keeps, the timeline's skyDarken the raw fold subtracts)
        world.day_tick = Some(18_000);
        let (px, pz) = (32.0, 32.0);
        let mut spawned = None;
        for seed in 0u64..64 {
            let mut mobs = Vec::new();
            let mut next_id = 1;
            let mut rng = Lcg::new(seed);
            if try_spawn(&mut mobs, &mut next_id, px, pz, &world, &mut rng, true) > 0 {
                spawned = Some(mobs.pop().unwrap());
                break;
            }
        }
        let z = spawned.expect("a night attempt lands within 64 seeds");
        // the distance law: the walked cell the 576.0 gate's own strict
        // arm re-checks (the anchor's ring the ±5 random walk the
        // attempt's own draws drift — the gate the closer cell refuses,
        // the upper band the walk's own reach the drift extends)
        let dx = z.x - px;
        let dz = z.z - pz;
        let d = (dx * dx + dz * dz).sqrt();
        assert!(
            d >= SPAWN_MIN_DIST - 1.5,
            "distance {d} the gate's own strict law keeps"
        );
        // the surface law: the feet ride the FIXED anchor y the walk
        // never rescans — the below cell solid the face-sturdy law
        // keeps (the walked column's own terrain the gate the step
        // refusals wear)
        let (bx, bz) = (z.x.floor() as i32, z.z.floor() as i32);
        let feet = z.y as i32;
        assert!(
            crate::body::solid(&world, bx, feet - 1, bz),
            "the below cell the surface's own solid wears"
        );
        // the head-room law: two free cells above
        assert!(!crate::body::solid(&world, bx, feet, bz));
        assert!(!crate::body::solid(&world, bx, feet + 1, bz));
        // the day gate: night=false never spawns
        let mut mobs = Vec::new();
        let mut next_id = 1;
        let mut rng = Lcg::new(99);
        assert_eq!(
            try_spawn(
                &mut mobs,
                &mut next_id,
                px,
                pz,
                &world,
                &mut rng,
                false
            ),
            0,
            "the day gate the pack never arms"
        );
        assert!(mobs.is_empty());
    }

    /// THE EQUIPMENT'S OWN GATE the draw counts keep (javap
    /// `populateDefaultEquipmentSlots` the mirror pair speaks): the
    /// verdict the ONE gate draw the unarmed spawn spends, the armed
    /// the nextInt(6) pick the second draw answers — the post-call
    /// streams the same count consumed the re-join keeps (the mirror
    /// stream the identical walk replays, the next() the fork's own
    /// word re-speaks).
    #[test]
    fn the_equipment_the_gate_the_draw_counts_keep() {
        for seed in 0u64..300 {
            let mut d = Lcg::new(seed);
            let got = spawn_equipment(&mut d);
            // the mirror: the gate nextFloat, the armed the nextInt(6)
            let mut m = Lcg::new(seed);
            let want = if m.next_f32() < 0.01 {
                Some(match m.next_int(6) {
                    0 => "iron_sword",
                    1 => "iron_spear",
                    _ => "iron_shovel",
                })
            } else {
                None
            };
            assert_eq!(got, want, "seed {seed} the verdict the mirror keeps");
            // the draw-count law: the streams re-join (the unarmed the
            // ONE draw spent, the armed the TWO)
            assert_eq!(d.next(), m.next(), "seed {seed} the stream re-joins");
        }
    }

    /// THE EQUIPMENT'S OWN SPLIT the arms keep: the armed seeds the
    /// three words all speak — the 0 the sword, the 1 the spear (the
    /// 26.2's own new item), the 2..=5 the four arms the shovel keeps;
    /// the 1% band the binomial's own 3-sigma the seed scan keeps.
    #[test]
    fn the_equipment_the_split_the_arms_keep() {
        let mut sword = 0;
        let mut spear = 0;
        let mut shovel = 0;
        for seed in 0u64..20000 {
            let mut d = Lcg::new(seed);
            if let Some(w) = spawn_equipment(&mut d) {
                // the pick the mirror re-speaks
                let mut m = Lcg::new(seed);
                m.next_f32();
                let pick = m.next_int(6);
                match (w, pick) {
                    ("iron_sword", 0) => sword += 1,
                    ("iron_spear", 1) => spear += 1,
                    ("iron_shovel", 2..=5) => shovel += 1,
                    _ => panic!("seed {seed} the word {w} the pick {pick} never pairs"),
                }
            }
        }
        assert!(sword > 0 && spear > 0 && shovel > 0, "the three arms speak");
        // the 1% band: 20000 * 0.01 = 200, sigma ~14 — the 3-sigma walk
        let armed = sword + spear + shovel;
        assert!(
            (110..=290).contains(&armed),
            "armed {armed} the 1% band keeps"
        );
        // the split law: the four shovel arms the sword/spear pair leads
        // (the 4:1:1 the nextInt(6) split speaks — the counts the ratio
        // the loose band keeps)
        assert!(shovel > sword * 2, "shovel {shovel} the 4:1 lead keeps");
        assert!(shovel > spear * 2, "shovel {shovel} the 4:1 lead keeps");
    }

    /// THE PACK MIRROR'S OWN RNG SKELETON (the flat world the spot
    /// gates the uniform pass keeps — the mirror the try_spawn's draw
    /// order replays: the anchor's two f64s, per walk the budget f32,
    /// per attempt the four nextInt(6)s + the distance gate + the
    /// once-per-walk kind roll + the pack roll + the light gate's pair
    /// + the spawn's ctor seed + the yaw + the zombie chain the group
    /// data's null arm keeps + the equipment gate — the LAST spawn's
    /// own word the ledger pairs).
    fn pack_mirror_last_weapon(seed: u64, world: &World) -> Option<Option<&'static str>> {
        let mut p = Lcg::new(seed);
        let ang = p.next_f64() * std::f64::consts::TAU;
        let dist = SPAWN_MIN_DIST + p.next_f64() * (SPAWN_MAX_DIST - SPAWN_MIN_DIST);
        let ax = ((32.0 + ang.cos() * dist).floor()) as i32;
        let az = ((32.0 + ang.sin() * dist).floor()) as i32;
        // the anchor's own surface scan (the no-draw read the real walk
        // speaks — the fixed y the walked cells attempt at)
        let mut fy_opt: Option<i32> = None;
        for y in (0..world.size_blocks()).rev() {
            if crate::body::solid(world, ax, y, az) {
                fy_opt = Some(y + 1);
                break;
            }
        }
        let fy = fy_opt?;
        let mut last: Option<Option<&'static str>> = None;
        let mut spawned = 0usize;
        'walks: for _ in 0..3 {
            let mut budget = (p.next_f32() * 4.0).ceil() as i32;
            let mut group_baby: Option<bool> = None;
            let mut kind: Option<i32> = None;
            let mut attempt = 0;
            let mut wx = ax;
            let mut wz = az;
            while attempt < budget {
                wx += p.next_int(6) - p.next_int(6);
                wz += p.next_int(6) - p.next_int(6);
                let dx = wx as f64 + 0.5 - 32.0;
                let dz = wz as f64 + 0.5 - 32.0;
                if dx * dx + dz * dz <= 576.0 {
                    attempt += 1;
                    continue;
                }
                let roll = match kind {
                    Some(r) => r,
                    None => {
                        let r = p.next_int(390);
                        let _pack = p.next_int(1);
                        budget = MONSTER_PACK_MIN;
                        kind = Some(r);
                        r
                    }
                };
                // THE SPOT'S OWN SOLID CHECKS FIRST (the short-circuit
                // the real walk's || chain keeps — the failed solid the
                // light gate never reaches, the draws the refusal never
                // spends — the out-of-bounds drift the honest silence
                // wears)
                if !crate::body::solid(world, wx, fy - 1, wz)
                    || crate::body::solid(world, wx, fy, wz)
                    || crate::body::solid(world, wx, fy + 1, wz)
                {
                    attempt += 1;
                    continue;
                }
                // the light gate: the sky 15 the stage-1 pass, the raw 4
                // the uniform's upper half admits
                let gate32 = p.next_int(32);
                if gate32 < 15 {
                    attempt += 1;
                    continue;
                }
                let gate8 = p.next_int(8);
                if gate8 < 4 {
                    attempt += 1;
                    continue;
                }
                let _ctor_seed = p.next();
                let _yaw = p.next_f32();
                let want = if roll < 100 {
                    // THE SPIDER's own finalizeSpawn — the NORMAL world
                    // the HARD-gated effect arm never spends, the group
                    // data no draw carries
                    None
                } else if roll < 190 {
                    // THE ZOMBIE's own group-data walk — the null arm's
                    // draw A the walk's members share, the jockey roll B
                    // per baby member (the && short-circuit the missed
                    // verdict the B draw never spends), the chicken gate
                    // C the hen's ctor seed + the baby roll D the armed
                    // arm spends, the equipment gate the tail rides
                    let baby = match group_baby {
                        Some(v) => v,
                        None => {
                            let v = p.next_f32() < 0.05;
                            group_baby = Some(v);
                            v
                        }
                    };
                    if baby && p.next_f32() < 0.05 {
                        if p.next_f32() < 0.05 {
                            p.next();
                            p.next_f32();
                        }
                    }
                    if p.next_f32() < 0.01 {
                        Some(match p.next_int(6) {
                            0 => "iron_sword",
                            1 => "iron_spear",
                            _ => "iron_shovel",
                        })
                    } else {
                        None
                    }
                } else if roll < 290 {
                    // THE SKELETON's own populate — the unconditional BOW
                    // the no-draw law keeps
                    Some("bow")
                } else {
                    // THE CREEPER's own finalizeSpawn — the draw-free lane
                    None
                };
                last = Some(want);
                spawned += 1;
                if spawned >= MONSTER_CLUSTER_SIZE as usize {
                    break 'walks;
                }
                attempt += 1;
            }
        }
        last
    }

    /// THE PACK'S OWN SHAPE the walk wears (javap spawnCategoryForPosition
    /// the 26.2 bytecode speaks): ONE call the pack's own multiple mobs
    /// spawns (the old single-attempt lane the one-body silence wore),
    /// the once-per-walk KIND draw the walk's members the same kind
    /// wears, the cluster cap the 4-mob ceiling the whole pack the
    /// walks never pass, the walked cells the ±5 scatter the anchor's
    /// own ring the gate's strict arm re-checks.
    #[test]
    fn the_pack_the_walks_the_same_kind_the_cluster_cap_wears() {
        let mut world = jockey_flat_world();
        world.day_tick = Some(18_000);
        world.relight();
        let (px, pz) = (32.0, 32.0);
        let mut landed = false;
        for seed in 0u64..512 {
            let mut mobs = Vec::new();
            let mut next_id = 1;
            let n = try_spawn(&mut mobs, &mut next_id, px, pz, &world, &mut Lcg::new(seed), true);
            if n < 2 {
                continue;
            }
            // THE CLUSTER CAP the whole call never passes
            assert!(n <= MONSTER_CLUSTER_SIZE as usize, "n {n} the cap keeps");
            // THE ONCE-PER-WALK KIND the same walk's members wear — the
            // pack the walk boundaries the kind groups split (up to the
            // three kinds the three walks speak)
            let mut kinds: Vec<MobKind> = mobs.iter().map(|m| m.kind).collect();
            kinds.dedup_by(|a, b| a == b);
            assert!(
                kinds.len() <= 3,
                "the walk groups the same-kind members keep (kinds {kinds:?})"
            );
            // the walked cells the 576.0 gate's own strict arm re-checks
            for m in &mobs {
                let dx = m.x - px;
                let dz = m.z - pz;
                assert!(
                    dx * dx + dz * dz > 576.0,
                    "the walked cell the gate's own strict law keeps"
                );
            }
            landed = true;
            break;
        }
        assert!(landed, "a multi-mob pack lands within 512 seeds");
    }

    /// THE SPAWN'S OWN LEDGER the weapon writes (try_spawn the pack
    /// walk's own order pin keeps): the anchor's ring draws, the walk's
    /// budget roll, the ±5 scatter, the once-per-walk KIND draw, the
    /// pack roll, the gate's pair, the ctor seed, the yaw, the zombie
    /// chain (the group data the walk's members share), the equipment
    /// gate the zombie's tail rides — the mirror walk the identical
    /// draws replays, the verdict the spawned pack's LAST mob's own
    /// word pairs.
    #[test]


    fn the_spawn_the_weapon_the_natural_writes() {
        let mut world = jockey_flat_world();
        // the midnight clock the gate's stage 3 wears — the FLAT world
        // the uniform column the mirror's own replay speaks (the
        // procedural terrain's canopy attenuation the ledger's law
        // never needed)
        world.day_tick = Some(18_000);
        world.relight();
        let (px, pz) = (32.0, 32.0);
        let mut armed = 0;
        let mut pinned = 0;
        for seed in 0u64..800 {
            let mut mobs = Vec::new();
            let mut next_id = 1;
            let mut rng = Lcg::new(seed);
            if try_spawn(&mut mobs, &mut next_id, px, pz, &world, &mut rng, true) == 0 {
                continue;
            }
            let z = mobs.pop().unwrap();
            if z.held_weapon.is_some() {
                armed += 1;
            }
            // the mirror walk: the pack skeleton the identical draws
            // replays (the flat world's own spot gates the mirror's own
            // solid model replays) — the LAST spawn's own word the ledger
            // pairs
            let want = pack_mirror_last_weapon(seed, &world)
                .expect("the spawned seed the mirror's own spawn replays");
            assert_eq!(
                z.held_weapon, want,
                "seed {seed} the weapon the ledger keeps"
            );
            pinned += 1;
        }
        assert!(pinned >= 100, "pinned {pinned} the spawn band keeps");
        // the 1% gate the 400-seed band arms (mean 4, sigma 2 — the
        // loose 1 the flake never rides)
        assert!(armed >= 1, "armed {armed} the gate the band arms");
        // the replay: the same seed the same word (the determinism the
        // spawn law keeps) — the FIRST spawning seed the gate's own
        // texture speaks (the refusals the stream the honest texture
        // wears, the replay the spawned mob's word pairs)
        let replay_seed = (0u64..)
            .find(|&s| {
                let mut mobs = Vec::new();
                let mut next_id = 1;
                try_spawn(&mut mobs, &mut next_id, px, pz, &world, &mut Lcg::new(s), true) > 0
            })
            .expect("a midnight attempt lands within the band");
        let mut mobs = Vec::new();
        let mut next_id = 1;
        let mut rng = Lcg::new(replay_seed);
        try_spawn(&mut mobs, &mut next_id, px, pz, &world, &mut rng, true);
        let a = mobs.pop().unwrap().held_weapon;
        let mut mobs = Vec::new();
        let mut next_id = 1;
        let mut rng = Lcg::new(replay_seed);
        try_spawn(&mut mobs, &mut next_id, px, pz, &world, &mut rng, true);
        assert_eq!(a, mobs.pop().unwrap().held_weapon, "the replay the word keeps");
    }

    /// THE PLAINS MONSTER TABLE'S OWN ROWS (the jar's worldgen json the
    /// 26.2 keeps — spider 100, zombie 90, skeleton 100, creeper 100,
    /// the admitted total 390 the NaturalSpawner's WeightedList.getRandom
    /// draws): the night's own roll the FOUR kinds split, the vanilla
    /// list order the ranges keep (the SPIDER row FIRST — the [0, 100)
    /// range rides — the zombie the [100, 190) band answers, the
    /// skeleton the [190, 290) tail keeps, the creeper the [290, 390)
    /// end wears), the PACK WALK the once-per-walk draw the same roll
    /// speaks (the walk's members the same kind the pack wears, the
    /// cluster cap the 4-mob ceiling keeps), the skeleton's own populate
    /// the unconditional BOW the no-draw law keeps (javap
    /// `AbstractSkeleton.populateDefaultEquipmentSlots` — the super
    /// the Monster base keeps, the setItemSlot(MAINHAND,
    /// Items.BOW) the getstatic/invoke pair arms), the group-data
    /// baby/jockey rolls the skeleton's finalizeSpawn never carries —
    /// the spawned bone-bags the ADULT the bow the hand always wear —
    /// and the SPIDER and THE CREEPER the same draw-free lane keeps
    /// (the NORMAL world the HARD-gated effect arm never spends): the
    /// bare arachnid the string pool alone answers at the death, the
    /// bare creeper the gunpowder pool.
    #[test]
    fn the_skeleton_rows_the_plains_table_names() {
        let mut world = jockey_flat_world();
        // the midnight clock the gate's stage 3 wears (the live lane's
        // own law — the flat world's uniform column the sky 15 keeps)
        world.day_tick = Some(18_000);
        let (px, pz) = (32.0, 32.0);
        let mut zombies = 0;
        let mut skeletons = 0;
        let mut spiders = 0;
        let mut creepers = 0;
        for seed in 0u64..2400 {
            let mut mobs = Vec::new();
            let mut next_id = 1;
            if try_spawn(&mut mobs, &mut next_id, px, pz, &world, &mut Lcg::new(seed), true) == 0 {
                continue;
            }
            let kinds: Vec<MobKind> = mobs.iter().map(|m| m.kind).collect();
            for z in &mobs {
                match z.kind {
                    MobKind::Zombie => zombies += 1,
                    MobKind::Skeleton => {
                        skeletons += 1;
                        // THE BOW THE HAND ALWAYS WEARS (the populate's own
                        // unconditional law the roll never splits)
                        assert_eq!(
                            z.held_weapon,
                            Some("bow"),
                            "seed {seed} the bow the skeleton's own populate arms"
                        );
                        // THE GROUP-DATA ROLLS THE SKELETON NEVER SPENDS —
                        // no baby the ZombieGroupData lane could arm, no
                        // jockey the chicken search could link
                        assert!(!z.is_baby(), "the baby rolls the zombie lane alone keeps");
                        assert!(z.vehicle.is_none(), "the jockey search the skeleton never speaks");
                    }
                    MobKind::Spider => {
                        spiders += 1;
                        // THE BARE ARACHNID (the draw-free finalize the
                        // NORMAL world keeps — no equipment the lane
                        // could arm, no baby the Monster chain never
                        // carries, the MAX_HEALTH 16.0 the clinit keeps)
                        assert_eq!(
                            z.held_weapon, None,
                            "seed {seed} the spider the no-draw lane keeps bare"
                        );
                        assert!(!z.is_baby(), "the spider the baby lane never carries");
                        assert!(z.vehicle.is_none(), "the jockey search the spider never speaks");
                        assert_eq!(
                            z.health, SPIDER_MAX_HEALTH,
                            "the spider's own MAX_HEALTH the clinit keeps"
                        );
                    }
                    MobKind::Creeper => {
                        creepers += 1;
                        // THE BARE CREEPER (the draw-free finalize the
                        // NORMAL world keeps — no equipment the lane could
                        // arm, no baby the Monster chain never carries, the
                        // MAX_HEALTH 20.0 the registered default keeps)
                        assert_eq!(
                            z.held_weapon, None,
                            "seed {seed} the creeper the no-draw lane keeps bare"
                        );
                        assert!(!z.is_baby(), "the creeper the baby lane never carries");
                        assert!(z.vehicle.is_none(), "the jockey search the creeper never speaks");
                        assert_eq!(
                            z.health, CREEPER_MAX_HEALTH,
                            "the creeper's own registered default the base speaks"
                        );
                    }
                    // THE JOCKEY'S OWN HEN the pack may carry (the empty
                    // search's own spawn the rider's pose wears — not a
                    // draw kind, the count the four admitted rows keep)
                    MobKind::Chicken => {}
                    _ => panic!("the plains monster roll the four admitted kinds alone speak"),
                }
            }
            // the same seed the same pack (the determinism the spawner keeps)
            let mut mobs2 = Vec::new();
            let mut next_id = 1;
            try_spawn(&mut mobs2, &mut next_id, px, pz, &world, &mut Lcg::new(seed), true);
            let kinds2: Vec<MobKind> = mobs2.iter().map(|m| m.kind).collect();
            assert_eq!(kinds, kinds2, "seed {seed} the replay the pack keeps");
        }
        // the 100/90/100/100 split the spawned band arms (the flat
        // world's own bounds the ring's far half refuses, the GATE's
        // own texture the midnight spawn rate wears — the sky 17/32
        // and the uniform's upper half the per-attempt rate speak —
        // the FRACTION the roll tracks: the ~0.26 the spider and the
        // skeleton and the creeper means, the zombie's ~0.235 — the
        // pack walk the per-seed spawn count the same rolls multiply,
        // the shares the roll-INDEPENDENT gate the kinds share never
        // splits)
        let total = zombies + skeletons + spiders + creepers;
        let skel_pct = if total > 0 { skeletons * 100 / total } else { 0 };
        let spider_pct = if total > 0 { spiders * 100 / total } else { 0 };
        let creeper_pct = if total > 0 { creepers * 100 / total } else { 0 };
        let zombie_pct = if total > 0 { zombies * 100 / total } else { 0 };
        assert!(total > 200, "spawns {total} the band arms");
        assert!(
            skel_pct > 19 && skel_pct < 34,
            "skeleton share {skel_pct}% the skeleton row the [190, 290) range rides"
        );
        assert!(
            spider_pct > 19 && spider_pct < 34,
            "spider share {spider_pct}% the spider row the [0, 100) range rides"
        );
        assert!(
            creeper_pct > 19 && creeper_pct < 34,
            "creeper share {creeper_pct}% the creeper row the [290, 390) range rides"
        );
        assert!(
            zombie_pct > 16 && zombie_pct < 31,
            "zombie share {zombie_pct}% the zombie row the [100, 190) band rides"
        );
    }

    /// THE SPAWN GATE THE LIVE GRID THE THREE STAGES WEAR (autopush-424
    /// — the 26.2 `isDarkEnoughToSpawn` law the direct walk pins): the
    /// MIDNIGHT surface the raw 4 the probabilistic texture speaks
    /// (both verdicts the seeds wear), the TORCH cell the block
    /// ceiling's own every-seed refusal (the stage 2 the draw never
    /// asks — the torch law the field's protection wears), the NOON
    /// surface the raw 15 the uniform never admits (the day law the
    /// gate alone answers), the THUNDER-NOON the storm's flat-10 the
    /// raw 5 the upper band admits (the famous thunder-day spawns the
    /// both-verdict texture wears where the dry noon refused all), the
    /// CAVE cell the raw 0 the every-draw pass wears. The LIVE grid the
    /// walk answers (the relight the initial compute, the set's own
    /// incremental update the torch's emission the v0.3.444 walk
    /// carries).
    #[test]
    fn the_spawn_gate_the_live_grid_the_three_stages_wear() {
        // the flat GRASS world, lit, the midnight clock (darken 11)
        let mut world = jockey_flat_world();
        world.day_tick = Some(18_000);
        world.relight();
        // THE MIDNIGHT SURFACE: sky 15, block 0, raw 4 — the stage-1
        // pass (17/32) then the uniform's upper half (4/8) — both
        // verdicts the seeds speak
        let mut passes = 0;
        for seed in 0u64..256 {
            let mut rng = Lcg::new(seed);
            if is_dark_enough_to_spawn(&world, 32, 9, 32, &mut rng) {
                passes += 1;
            }
        }
        assert!(
            passes > 0 && passes < 256,
            "the midnight texture the {passes}/256 speaks"
        );
        // THE TORCH LAW: the torch on the cell the set walk's own
        // incremental emission answers (the live grid the edit keeps
        // current) — the block 14 the stage-2 ceiling refuses — EVERY
        // seed (the stage 2 the draw never spends)
        world.set(32, 9, 32, crate::world::TORCH);
        let (sky, block) = spawn_cell_light(&world, 32, 9, 32);
        assert_eq!(sky, 15, "the torch the sky column never dims");
        assert_eq!(block, 14, "the torch's own emission the live grid speaks");
        for seed in 0u64..64 {
            let mut rng = Lcg::new(seed);
            assert!(
                !is_dark_enough_to_spawn(&world, 32, 9, 32, &mut rng),
                "seed {seed} the torch the every-seed refusal wears"
            );
        }
        // THE NOON LAW: the dry noon's darken 0 — the raw 15 the
        // uniform never admits — EVERY seed refuses (the day spawns
        // the gate alone the vanilla law answers)
        let mut noon = jockey_flat_world();
        noon.day_tick = Some(6_000);
        noon.relight();
        for seed in 0u64..64 {
            let mut rng = Lcg::new(seed);
            assert!(
                !is_dark_enough_to_spawn(&noon, 32, 9, 32, &mut rng),
                "seed {seed} the noon the every-seed refusal wears"
            );
        }
        // THE THUNDER-DAY: the storm's flat-10 darkness the branch
        // passes — the raw 5 the draw's upper band admits — the
        // both-verdict texture where the dry noon refused all
        noon.thunder_level = 1.0;
        let mut storm_passes = 0;
        for seed in 0u64..256 {
            let mut rng = Lcg::new(seed);
            if is_dark_enough_to_spawn(&noon, 32, 9, 32, &mut rng) {
                storm_passes += 1;
            }
        }
        assert!(
            storm_passes > 0 && storm_passes < 256,
            "the thunder-day texture the {storm_passes}/256 speaks"
        );
        // THE CAVE LAW: the sealed pocket UNDER the ground (the stone
        // y 0..8 the jockey world wears, the one-cell pocket the carve
        // opens) — the sky 0 the opaque ring the flood never reaches,
        // the raw 0 the every-draw pass wears — EVERY seed admits
        let mut cave = jockey_flat_world();
        cave.day_tick = Some(18_000);
        cave.set(32, 4, 32, crate::world::AIR);
        cave.relight();
        let (cave_sky, cave_block) = spawn_cell_light(&cave, 32, 4, 32);
        assert_eq!(cave_sky, 0, "the stone ring the flood the grid keeps dark");
        assert_eq!(cave_block, 0, "the cave the no-emitter dark keeps");
        for seed in 0u64..64 {
            let mut rng = Lcg::new(seed);
            assert!(
                is_dark_enough_to_spawn(&cave, 32, 4, 32, &mut rng),
                "seed {seed} the cave the every-seed pass wears"
            );
        }
    }

    /// THE SPAWNER THE GATE THE NIGHT LAW WEARS (autopush-424 — the
    /// gate through try_spawn's own walk): the NOON world the caller's
    /// night arm rides (the client's beat the sun angle stands in) yet
    /// the gate the raw 15 EVERY attempt refuses, the MIDNIGHT world
    /// the same attempts the spawns speak (the gate's own texture the
    /// seeds wear). The torch-lit field the spawner never fills — the
    /// vanilla law the player's own torches the night protection
    /// speaks.
    #[test]
    fn the_spawner_the_gate_the_night_law_wears() {
        // the noon: every attempt the gate refuses
        let mut noon = jockey_flat_world();
        noon.day_tick = Some(6_000);
        noon.relight();
        for seed in 0u64..64 {
            let mut mobs = Vec::new();
            let mut next_id = 1;
            assert_eq!(
                try_spawn(&mut mobs, &mut next_id, 32.0, 32.0, &noon, &mut Lcg::new(seed), true),
                0,
                "seed {seed} the noon the every-attempt refusal wears"
            );
        }
        // the midnight: the spawns the texture speaks
        let mut midnight = jockey_flat_world();
        midnight.day_tick = Some(18_000);
        midnight.relight();
        let mut spawned = 0;
        for seed in 0u64..64 {
            let mut mobs = Vec::new();
            let mut next_id = 1;
            if try_spawn(&mut mobs, &mut next_id, 32.0, 32.0, &midnight, &mut Lcg::new(seed), true)
                > 0
            {
                spawned += 1;
            }
        }
        assert!(spawned > 0, "the midnight the {spawned}/64 spawns speak");
        // THE TORCH FIELD: the same midnight world, the torch ON every
        // attempt's own... the whole floor the torches light — the
        // block ceiling the spawner never passes (every attempt
        // refuses — the stage 2 the field's own protection wears)
        for x in 0..16 {
            for z in 0..16 {
                midnight.set(x * 4, 9, z * 4, crate::world::TORCH);
            }
        }
        let mut torch_spawned = 0;
        for seed in 0u64..64 {
            let mut mobs = Vec::new();
            let mut next_id = 1;
            if try_spawn(&mut mobs, &mut next_id, 32.0, 32.0, &midnight, &mut Lcg::new(seed), true)
                > 0
            {
                torch_spawned += 1;
            }
        }
        assert_eq!(
            torch_spawned, 0,
            "the torch field the every-attempt refusal wears"
        );
    }

    /// THE SPAWN BEAT THE BRIGHT-OUTSIDE WORD WEARS (autopush-425 —
    /// the beat's day/night arm the mob goals' own fn speaks): the
    /// darken track's own edges the arm windows keep, the sun's sin
    /// sign the OLD stand-in wore the contrasts pin (the dusk the
    /// creature arm rode, the pre-dawn and the morning the monster
    /// arm rode — the wrong halves the darken law retires).
    #[test]
    fn the_spawn_beat_the_bright_outside_word_wears() {
        // THE WINDOW EDGES (the sky_light_level ramps' own f32 law —
        // the dusk the darken lands 4 at 12_523, the dawn it lifts at
        // 23_478: the night the [12_523, 23_477] band the monster arm
        // wears, the day the wrap's bright half the creature arm
        // keeps — the ramps the mirrored values wear, the dusk's
        // 0.73359215 the dawn's own 0.7335922 the boundary answers)
        assert!(is_bright_outside(12_522), "the last bright dusk tick");
        assert!(!is_bright_outside(12_523), "the first dark tick");
        assert!(!is_bright_outside(23_477), "the last dark pre-dawn tick");
        assert!(is_bright_outside(23_478), "the first bright pre-dawn tick");
        assert!(is_bright_outside(6_000), "noon the creature arm keeps");
        assert!(!is_bright_outside(18_000), "midnight the monster arm keeps");
        // THE OLD WORD'S MIS-VERDICTS (the sin sign the stand-in wore
        // — the contrasts the fix's own story carries): the dusk
        // 12_600 the darken law the MONSTER arm keeps while the sun's
        // sin the CREATURE arm the old gate rode; the pre-dawn 23_500
        // and the morning 1_000 the bright word the CREATURE arm
        // keeps while the sin the MONSTER arm the old gate rode
        assert!(!is_bright_outside(12_600), "the dusk the monster arm wears");
        assert!(
            crate::sky::sample(12_600).sun_angle.sin() > 0.0,
            "the old gate's sin the dusk the creature arm rode"
        );
        assert!(is_bright_outside(23_500), "the pre-dawn the creature arm keeps");
        assert!(
            crate::sky::sample(23_500).sun_angle.sin() < 0.0,
            "the old gate's sin the pre-dawn the monster arm rode"
        );
        assert!(is_bright_outside(1_000), "the morning the creature arm keeps");
        assert!(
            crate::sky::sample(1_000).sun_angle.sin() < 0.0,
            "the old gate's sin the morning the monster arm rode"
        );
    }

    /// THE DESPAWN THE DISTANCE ARMS THE COUNTER WEARS (dev-36 — the
    /// `Mob.checkDespawn` walk the ServerLevel tick lambda arms BEFORE
    /// the tick): the far band the 128² fold speaks, the idle band the
    /// counter's own gate the roll's short-circuit wears, the tail's
    /// within-32 reset the near player keeps, the strict edges the
    /// double compares pin.
    #[test]
    fn the_despawn_the_distance_arms_the_counter_wear() {
        // THE FAR BAND (d0 > 16384 the instant discard the
        // removeWhenFarAway default keeps — the counter's state the
        // arm never reads: the fresh-zero body AND the idle-counted
        // one the same verdict wears)
        let mut far = Zombie::new(1, 130.0, 0.0, 0.0, 7);
        assert!(
            far.check_despawn(Some(&player_at(0.0, 0.0, 0.0))),
            "the 130-block ring the far band discards"
        );
        far.no_action_time = 601;
        assert!(
            far.check_despawn(Some(&player_at(0.0, 0.0, 0.0))),
            "the far band the counter's state never reads"
        );
        // THE STRICT EDGE (d0 == 16384.0 the `>` refuses — the exact
        // 128-block ring the walk keeps)
        let mut edge = Zombie::new(2, MOB_DESPAWN_DISTANCE, 0.0, 0.0, 7);
        edge.no_action_time = 601;
        assert!(
            !edge.check_despawn(Some(&player_at(0.0, 0.0, 0.0))),
            "the exact 128 ring the strict compare keeps"
        );
        // THE Y TERM (the feet-to-feet fold the 3D sum speaks — the
        // 200-block column the far band discards, the 100-block one
        // the horizontal bands' own verdict keeps)
        let mut above = Zombie::new(3, 0.0, 200.0, 0.0, 7);
        assert!(
            above.check_despawn(Some(&player_at(0.0, 0.0, 0.0))),
            "the 200-block column the y term the far band discards"
        );
        let mut near_above = Zombie::new(4, 0.0, 100.0, 0.0, 7);
        near_above.no_action_time = 0;
        assert!(
            !near_above.check_despawn(Some(&player_at(0.0, 0.0, 0.0))),
            "the 100-block column the bands' verdicts keep (the counter fresh)"
        );
        // THE NULL PLAYER (the walk's ifnull return — the verdict false,
        // the counter the absent player's arm never resets)
        let mut alone = Zombie::new(5, 0.0, 0.0, 0.0, 7);
        alone.no_action_time = 700;
        assert!(
            !alone.check_despawn(None),
            "the absent player the walk's null return keeps"
        );
        assert_eq!(alone.no_action_time, 700, "the null arm the counter keeps");
        // THE WITHIN-32 RESET (the walk's tail — the near player the
        // idle clock never banks: the counter the zero the reset
        // writes)
        let mut near = Zombie::new(6, 10.0, 0.0, 0.0, 7);
        near.no_action_time = 700;
        assert!(
            !near.check_despawn(Some(&player_at(0.0, 0.0, 0.0))),
            "the near body the far band refuses, the idle band the fresh counter refuses"
        );
        assert_eq!(
            near.no_action_time, 0,
            "the within-32 fold the counter's own reset wears"
        );
        // THE EXACT-1024 EDGE (the idle band's `>` AND the reset's `<`
        // BOTH refuse — the honest gap the strict pair the counter
        // rides through: 32.0 east = 1024.0 exactly)
        let mut band_edge = Zombie::new(7, MOB_NO_DESPAWN_DISTANCE, 0.0, 0.0, 7);
        band_edge.no_action_time = 700;
        assert!(
            !band_edge.check_despawn(Some(&player_at(0.0, 0.0, 0.0))),
            "the exact 32 ring both arms refuse"
        );
        assert_eq!(
            band_edge.no_action_time, 700,
            "the strict edges the counter rides through"
        );
        // THE HURT'S OWN RESET (the every-dose arm the counter zeroes
        // — the attacked mob the idle band never fills)
        let mut struck = Zombie::new(8, 10.0, 0.0, 0.0, 7);
        struck.no_action_time = 700;
        struck.hurt(1.0, true);
        assert_eq!(struck.no_action_time, 0, "the dose the counter zeroes");
        // THE SERVER AI STEP'S OWN HEAD (the ++ every tick the walk
        // keeps — two ticks the counter's own climb speaks)
        let world = ground_world();
        let mut grown = Zombie::new(9, 10.0, 5.0, 10.0, 7);
        grown.on_ground = true;
        grown.tick(&world, None, NIGHT);
        grown.tick(&world, None, NIGHT);
        assert_eq!(grown.no_action_time, 2, "the AI ticks the counter grows");
    }

    /// THE DESPAWN THE IDLE ROLL THE MOB'S OWN STREAM WEARS (dev-36 —
    /// the `nextInt(800)` roll the `this.random` field draws, the
    /// short-circuit the fresh-counted mob's stream never spends, the
    /// 1/800 texture the seed sweep speaks).
    #[test]
    fn the_despawn_the_idle_roll_the_own_stream_wears() {
        // THE ROLL-0 SEED (the sweep the first hit finds — the mob's
        // own LCG the 800-bound the first-zero seed speaks)
        let mut roll_zero_seed = None;
        for seed in 0..2400u64 {
            let mut probe = Zombie::new(1, 40.0, 0.0, 0.0, seed);
            probe.no_action_time = MOB_DESPAWN_IDLE_TICKS + 1;
            if probe.check_despawn(Some(&player_at(0.0, 0.0, 0.0))) {
                roll_zero_seed = Some(seed);
                break;
            }
        }
        let seed = roll_zero_seed.expect("the 1/800 texture the sweep lands");
        // THE FIRED WALK (the counter 601 + the roll zero + the 40-block
        // ring — the 1600.0 the idle band's own verdict wears) AND THE
        // STREAM'S OWN CONSUMPTION (exactly ONE nextInt(800) the fired
        // walk spent — the reference walk the same seed's own fold
        // answers)
        let mut fired = Zombie::new(2, 40.0, 0.0, 0.0, seed);
        fired.no_action_time = MOB_DESPAWN_IDLE_TICKS + 1;
        assert!(
            fired.check_despawn(Some(&player_at(0.0, 0.0, 0.0))),
            "the idle band the fired seed discards"
        );
        let mut reference = Zombie::new(3, 40.0, 0.0, 0.0, seed);
        let drawn = reference.rng.next_int(MOB_DESPAWN_IDLE_ROLL);
        assert_eq!(drawn, 0, "the seed the roll's own zero keeps");
        assert_eq!(
            fired.rng, reference.rng,
            "the fired walk exactly ONE draw the mob's own stream spent"
        );
        // THE SHORT-CIRCUIT (the counter at the gate's own edge — the
        // 600 the `>` refuses: NO draw the stream spends, the verdict
        // false — the roll the fresh-counted mob never pays; the
        // stream the PRISTINE walk's own state the compare answers)
        let mut fresh = Zombie::new(4, 40.0, 0.0, 0.0, seed);
        fresh.no_action_time = MOB_DESPAWN_IDLE_TICKS;
        assert!(
            !fresh.check_despawn(Some(&player_at(0.0, 0.0, 0.0))),
            "the 600 counter the strict gate keeps"
        );
        let pristine = Zombie::new(5, 40.0, 0.0, 0.0, seed);
        assert_eq!(
            fresh.rng, pristine.rng,
            "the gate the short-circuit keeps: the fresh-counted walk NO draw spends"
        );
        // THE DISTANCE'S OWN SHORT-CIRCUIT (the counter past the gate +
        // the roll zero + the ring INSIDE 32 — the third arm the
        // verdict refuses: the 30-block body the band keeps)
        let mut inside = Zombie::new(6, 30.0, 0.0, 0.0, seed);
        inside.no_action_time = MOB_DESPAWN_IDLE_TICKS + 1;
        assert!(
            !inside.check_despawn(Some(&player_at(0.0, 0.0, 0.0))),
            "the 30-block ring the idle band's distance arm refuses"
        );
        // THE TEXTURE (the 2400-seed sweep the ~1/800 band speaks — the
        // fired seeds the deterministic count the honest spread keeps)
        let mut fired_count = 0;
        for s in 0..2400u64 {
            let mut probe = Zombie::new(1, 40.0, 0.0, 0.0, s);
            probe.no_action_time = MOB_DESPAWN_IDLE_TICKS + 1;
            if probe.check_despawn(Some(&player_at(0.0, 0.0, 0.0))) {
                fired_count += 1;
            }
        }
        assert!(
            (1..=25).contains(&fired_count),
            "the 2400-seed sweep the ~3 expected band keeps: {fired_count}"
        );
    }

    /// THE FALLING TICK'S OWN PHYSICS (javap the tick's own order — the
    /// applyGravity the vy -= 0.04 step wears, the tail the getAirDrag
    /// 0.98 scale keeps: the recurrence v_{n+1} = (v_n - 0.04) * 0.98
    /// the mid-air body the honest floor never meets, the ++time the
    /// tick's own clock keeps).
    #[test]
    fn the_falling_block_the_gravity_the_drag_recurrence_wears() {
        let world = wide_flat_world();
        let mut f = FallingBlock::new(1, crate::world::SAND, 10, 30, 10);
        let mut expect = 0.0f64;
        for n in 1..=10u32 {
            expect = (expect - FALLING_BLOCK_GRAVITY) * FALLING_BLOCK_AIR_DRAG;
            assert!(!f.tick(&world), "the free air the landing never meets");
            assert!(
                (f.vy - expect).abs() < 1e-9,
                "tick {n} the recurrence the drag keeps"
            );
            assert_eq!(f.time, n, "the ++time the tick's own clock keeps");
        }
        // the fall's own descent (the ~2.2-block sum the ten ticks wear)
        assert!(f.y < 30.0 && f.y > 26.0, "the descent the gravity wears");
    }

