    /// THE EGG'S OWN CLOCK THE LAY CROSSES (javap `Chicken.aiStep`'s
    /// tail fold: the lazy arm the shared ctor's stream keeps, the
    /// gate the baby and the other kinds the countdown never rides,
    /// the zero crossing the pitch + the refill speaks, the dying the
    /// early return the fold never reaches).
    #[test]
    fn the_chicken_egg_the_clock_walks() {
        let world = ground_world();
        // THE LAZY ARM (the sentinel the shared ctor's draw keeps —
        // the first gated tick the 6000..12000 the ctor's own value
        // arms, the same distribution the vanilla ctor speaks)
        let mut hen = Zombie::new(1, 2.0, 5.0, 2.0, 7);
        hen.kind = MobKind::Chicken;
        hen.on_ground = true;
        assert_eq!(hen.egg_time, 0, "the ctor the draw never spends");
        hen.tick(&world, None, NIGHT);
        assert!(
            (6000..=12000).contains(&hen.egg_time),
            "the first gated tick the clock arms: {}",
            hen.egg_time
        );
        // the zombie the fold never reads (the sentinel the other
        // kinds keep)
        let mut z = Zombie::new(2, 2.0, 5.0, 2.0, 7);
        z.tick(&world, None, NIGHT);
        assert_eq!(z.egg_time, 0, "the zombie the egg clock never arms");
        // THE BABY GATE (the childhood the countdown pauses — the
        // vanilla law the held value through childhood speaks)
        let mut chick = Zombie::new(3, 2.0, 5.0, 2.0, 7);
        chick.kind = MobKind::Chicken;
        chick.set_age(BABY_START_AGE);
        chick.on_ground = true;
        chick.tick(&world, None, NIGHT);
        assert_eq!(chick.egg_time, 0, "the baby the gate never arms");
        // THE LAY'S OWN CROSSING (eggTime 1 -> the --eggTime the zero
        // crossing fires: the pitch the (0.8, 1.2) the (f1-f2)*0.2 law
        // keeps, the refill the 6000..12000 the tail arms, the draw
        // order the vanilla walk keeps — the pitches, then the refill)
        let mut ready = Zombie::new(4, 2.0, 5.0, 2.0, 7);
        ready.kind = MobKind::Chicken;
        ready.on_ground = true;
        ready.egg_time = 1;
        let ev = ready.tick(&world, None, NIGHT);
        let pitch = ev.egg_laid.expect("the lay the event speaks");
        assert!(
            (0.8..=1.2).contains(&pitch),
            "the pitch the (f1-f2)*0.2 law keeps: {pitch}"
        );
        assert!(
            (6000..=12000).contains(&ready.egg_time),
            "the refill the tail arms: {}",
            ready.egg_time
        );
        // THE DEAD HEN THE GATE REFUSES (the isAlive arm the early
        // return the fold never reaches)
        let mut dead = Zombie::new(5, 2.0, 5.0, 2.0, 7);
        dead.kind = MobKind::Chicken;
        dead.egg_time = 1;
        dead.hurt(1000.0, true);
        let ev = dead.tick(&world, None, NIGHT);
        assert!(ev.egg_laid.is_none(), "the dying the lay refuses");
    }

    #[test]
    fn the_wolf_kind_the_jar_words_speak() {
        // THE CANINE'S OWN PER-KIND TABLE (javap the 26.2 jar the
        // round's audits bank): the wire admission, the EntityTypes
        // block's dims + eye, the createAttributes triple's walk +
        // health, the registerGoals' stroll + the
        // TamableAnimalPanicGoal's environmental tag word, the
        // shouldBurnInDay base's false, the Animal chain's
        // not-a-monster, and the classic sound variant's voice rows
        let w = MobKind::from_wire_name("minecraft:wolf");
        assert_eq!(w, MobKind::Wolf);
        assert_eq!(w.eye_height(), WOLF_EYE_HEIGHT);
        assert!((WOLF_EYE_HEIGHT - 0.68).abs() < 1e-9, "the 0.68 the clinit keeps");
        assert_eq!(w.max_health(), WOLF_MAX_HEALTH);
        assert_eq!(WOLF_MAX_HEALTH, 8.0);
        assert_eq!(w.movement_speed(), WOLF_MOVEMENT_SPEED);
        assert!((WOLF_MOVEMENT_SPEED - 0.300_000_011_920_928_96).abs() < 1e-15);
        assert_eq!(w.stroll_speed(), 1.0, "the prio-8 stroll the dconst_1 keeps");
        assert_eq!(w.panic_speed(), None, "the environmental tag the hurt-flee never arms");
        assert!(!w.should_burn_in_day(), "the Mob base's own false the canine keeps");
        assert!(!w.is_monster(), "the Animal chain the Monster branch never reaches");
        let mut body = Zombie::new(7, 0.5, 5.0, 0.5, 9);
        body.kind = MobKind::Wolf;
        let (x0, y0, _z0, x1, y1, _z1) = body.box_for();
        let (bw, bh) = (x1 - x0, y1 - y0);
        assert!((bw - WOLF_WIDTH).abs() < 1e-9, "the sized 0.6");
        assert!((bh - WOLF_HEIGHT).abs() < 1e-9, "the sized 0.85 — the 26.2 word");
        assert_eq!(
            w.voice_event(VoiceSlot::Ambient),
            "entity.wolf.ambient",
            "the classic variant's own adult word"
        );
        assert_eq!(w.voice_event(VoiceSlot::Hurt), "entity.wolf.hurt");
        assert_eq!(w.voice_event(VoiceSlot::Death), "entity.wolf.death");
        assert_eq!(
            w.step_voice(None),
            Some(("entity.wolf.step", 0.15, 1.0)),
            "the playStepSound's flat fold the variant step wears"
        );
        // the loot: the empty pool the header-only table keeps
        let mut dying = Zombie::new(8, 0.5, 5.0, 0.5, 3);
        dying.kind = MobKind::Wolf;
        dying.health = 0.0;
        assert!(dying.death_loot(false).is_empty(), "the wolf drops nothing");
    }

    #[test]
    fn the_wolf_ambient_voice_the_four_arms_speak() {
        // javap `Wolf.getAmbientSound` — the FOUR arms the raw disasm
        // keeps: isAngry -> growl (the early areturn the roll never
        // draws); nextInt(3) == 0 -> (isTame && health < 20.0 ? whine :
        // pant); else the kind row's bark. The client's own LCG the
        // seeds drive: seed 0's next_int(3) = [0, 1, ...] (the roll arm
        // FIRST, the miss SECOND), seed 1's = [2, ...] (the miss first).
        // THE BARK ARM (seed 1 — the roll's miss the kind row wears):
        let mut shy = Zombie::new(21, 8.0, 5.0, 8.0, 1);
        shy.kind = MobKind::Wolf;
        assert_eq!(
            shy.ambient_voice_event(),
            Some("entity.wolf.ambient"),
            "the miss the bark keeps"
        );
        // THE WHINE ARM (seed 0 — the roll opens; the tamed hurt body
        // the ldc_w 20.0's own compare wears): the full-heal ceiling's
        // own tamed body at 15.0 the whine speaks
        let mut hurt = Zombie::new(22, 8.0, 5.0, 8.0, 0);
        hurt.kind = MobKind::Wolf;
        hurt.tamed = true;
        hurt.health = 15.0;
        assert_eq!(
            hurt.ambient_voice_event(),
            Some("entity.wolf.whine"),
            "the tamed hurt body the whine wears"
        );
        // THE PANT ARM — the WILD body (the isTame gate's false the
        // whine never wears, the same roll the pant answers):
        let mut wild = Zombie::new(23, 8.0, 5.0, 8.0, 0);
        wild.kind = MobKind::Wolf;
        wild.health = 15.0;
        assert_eq!(
            wild.ambient_voice_event(),
            Some("entity.wolf.pant"),
            "the wild body the pant answers"
        );
        // THE PANT ARM — the TAMED HEALTHY body (40.0 the ceiling
        // keeps, the 20.0 compare the whine refuses):
        let mut fed = Zombie::new(24, 8.0, 5.0, 8.0, 0);
        fed.kind = MobKind::Wolf;
        fed.tamed = true;
        fed.health = WOLF_TAMED_MAX_HEALTH;
        assert_eq!(
            fed.ambient_voice_event(),
            Some("entity.wolf.pant"),
            "the healthy tamed body the pant answers"
        );
        // THE GROWL ARM + THE NO-DRAW LAW (the angry body the growl
        // returns BEFORE the roll — seed 0's first draw the 0 word the
        // growl must leave untouched, the SECOND call's own roll the
        // same first draw speaks: a spent draw the 1 word the bark arm
        // would wear): the tamed healthy body the pant the roll arm
        // speaks again
        let mut angry = Zombie::new(25, 8.0, 5.0, 8.0, 0);
        angry.kind = MobKind::Wolf;
        angry.tamed = true;
        angry.health = WOLF_TAMED_MAX_HEALTH;
        angry.anger_ticks = 100;
        assert_eq!(
            angry.ambient_voice_event(),
            Some("entity.wolf.growl"),
            "the angry body the growl returns first"
        );
        angry.anger_ticks = 0;
        assert_eq!(
            angry.ambient_voice_event(),
            Some("entity.wolf.pant"),
            "the roll the growl never drew — the first 0 the same arm speaks"
        );
        // THE STATELESS KINDS (no arm their rows read — the zombie's
        // word the kind row keeps, the stream the clone law proves
        // untouched):
        let mut z = Zombie::new(26, 8.0, 5.0, 8.0, 0);
        let before = z.rng.clone();
        assert_eq!(z.ambient_voice_event(), Some("entity.zombie.ambient"));
        let (a, b) = (z.rng.next(), before.clone().next());
        assert_eq!(a, b, "the stateless walk the stream never spends");
        // THE WOLF'S STATELESS ROWS (the hurt/death words the state
        // never bends — the kind table's own rows the kind voice keeps):
        let mut w = Zombie::new(27, 8.0, 5.0, 8.0, 0);
        w.kind = MobKind::Wolf;
        w.tamed = true;
        assert_eq!(w.voice_event(VoiceSlot::Hurt), "entity.wolf.hurt");
        assert_eq!(w.voice_event(VoiceSlot::Death), "entity.wolf.death");
    }

    #[test]
    fn the_avoid_goal_the_scan_the_gates_keep() {
        // THE AVOIDENTITYGOAL'S OWN CANUSE RAW MATERIAL (the pre-pass
        // the caller's walk arms): the in-range wolf the nearest fold
        // arms, the 6.0-ring escape the range gate refuses, the
        // inflate(6, 3, 6) box the y law keeps, the dying wolf the
        // alive gate skips, the non-skeleton the kind gate never arms
        let mut mobs = Vec::new();
        // skeleton at the origin cell
        let mut skel = Zombie::new(1, 20.5, 5.0, 20.5, 11);
        skel.kind = MobKind::Skeleton;
        mobs.push(skel);
        // wolf IN range (5 blocks east)
        let mut w1 = Zombie::new(2, 25.5, 5.0, 20.5, 12);
        w1.kind = MobKind::Wolf;
        mobs.push(w1);
        assert_eq!(arm_skeleton_wolf_avoid(&mut mobs), 1);
        assert_eq!(mobs[0].live_wolf_seen.map(|(id, _, _, _)| id), Some(2));
        // the wolf OUT of the 6.0 ring (10 blocks north — the box gate
        // passes, the range law refuses)
        mobs[1].z = 30.5;
        assert_eq!(arm_skeleton_wolf_avoid(&mut mobs), 0);
        assert!(mobs[0].live_wolf_seen.is_none());
        // the DYING wolf the alive gate skips (in range, dead)
        mobs[1].z = 20.5;
        mobs[1].health = 0.0;
        assert_eq!(arm_skeleton_wolf_avoid(&mut mobs), 0);
        // the ZOMBIE the kind gate never arms (the AvoidEntityGoal the
        // skeleton's goalSelector alone wears)
        mobs[0].kind = MobKind::Zombie;
        mobs[1].health = 8.0;
        assert_eq!(arm_skeleton_wolf_avoid(&mut mobs), 0);
        assert!(
            mobs[0].avoid_target.is_none() && mobs[0].avoid_threat.is_none(),
            "the non-skeleton the fields never carry"
        );
    }

    #[test]
    fn the_avoid_goal_the_flee_the_sprint_law_wears() {
        // THE FLEE WALK (the straight-line stand-in the goal machine
        // keeps): the armed canUse the AWAY-biased roll arms (the
        // farther gate the 10-try walk passes on the open flat), the
        // skeleton walks AWAY from the wolf, the SPRINT the <49 ring
        // wears (the 1.2 the tick's dcmpg keeps), the arrival the
        // isDone law stops
        let world = wide_flat_world();
        let mut skel = Zombie::new(1, 20.5, 5.0, 20.5, 21);
        skel.kind = MobKind::Skeleton;
        let mut wolf = Zombie::new(2, 24.5, 5.0, 20.5, 22);
        wolf.kind = MobKind::Wolf;
        // the canUse arm: the pre-pass arms the scan, the tick's
        // canUse+start the AWAY roll keeps (the east wolf, the west
        // flee — the away direction the subtract speaks)
        let mut mobs = vec![skel, wolf];
        assert_eq!(arm_skeleton_wolf_avoid(&mut mobs), 1);
        // the threat's own distance law (the canUse's compare the
        // mob's CURRENT distance² the baseline keeps — the wolf the
        // east 4 the test keeps)
        let threat_d2 = |m: &Zombie| {
            let ddx = m.x - 24.5;
            let ddy = m.y - 5.0;
            let ddz = m.z - 20.5;
            ddx * ddx + ddy * ddy + ddz * ddz
        };
        let threat_d2_start = threat_d2(&mobs[0]);
        for _ in 0..10 {
            arm_skeleton_wolf_avoid(&mut mobs);
            mobs[0].tick(&world, None, NIGHT);
        }
        // THE CANUSE'S OWN WORD (the farther gate the canUse's compare
        // keeps): the skeleton the flee leaves FARTHER from the threat
        // than the walk began — the x-component the away ring's own
        // spread may keep (the vanilla law the total distance wears,
        // the axis the stand-in never promises)
        let threat_d2_end = threat_d2(&mobs[0]);
        assert!(
            threat_d2_end > threat_d2_start,
            "the flee walks AWAY (d2 {} -> {})",
            threat_d2_start,
            threat_d2_end
        );
        // the threat's id the goal holds (the toAvoid the running
        // goal keeps, the live pos the pre-pass refreshes)
        assert_eq!(mobs[0].avoid_threat.map(|(id, _, _, _)| id), Some(2));
        // THE SPRINT LAW (the tick's own dcmpg/ifge — the 49.0 the
        // threshold keeps: the 4-block ring the 1.2 sprint arms, the
        // 8-block ring the 1.0 walk answers — the squared law the
        // constants pin)
        assert!(4.0 * 4.0 < WOLF_AVOID_SPRINT_SQR);
        assert!(8.0 * 8.0 > WOLF_AVOID_SPRINT_SQR);
        // the arrival stop: the flee target reached, the stop()'s null
        // write the fields clear
        mobs[0].avoid_target = Some((mobs[0].x, mobs[0].y, mobs[0].z));
        let _ = mobs[0].tick(&world, None, NIGHT);
        assert!(
            mobs[0].avoid_target.is_none(),
            "the arrival the isDone law stops"
        );
    }

    /// THE BEGGOAL'S OWN WALK (the wolf's own registerGoals prio 9 the
    /// dump keeps — the canUse gate the interesting hand arms, the
    /// start's `40 + nextInt(40)` the entity's own stream draws, the
    /// tick's setLookAt the head's stare serves, the `--lookTime` the
    /// decrement walks, the swap-away the stop law answers)
    #[test]
    fn the_beg_goal_the_interesting_hand_arms() {
        let world = flat_world();
        let bone_id = mc_registry::item_id_by_name("bone").expect("the bone the registry keeps");
        // THE CANUSE (the TargetingConditions.forNonCombat().range(8.0)
        // the getNearestPlayer walk wears: the 3D 9 < 64 square, the
        // LOS open, the bone the gate's first arm names)
        let mut wolf = Zombie::new(1, 8.0, 5.0, 8.0, 4);
        wolf.kind = MobKind::Wolf;
        let mut pv = player_at(11.0, 5.0, 8.0);
        pv.held_item_id = Some(bone_id);
        let _ = wolf.tick(&world, Some(&pv), NOON);
        assert!(wolf.interested, "the bone the beg arms");
        assert!(
            wolf.beg_look_time >= BEG_LOOK_TIME_BASE
                && wolf.beg_look_time < BEG_LOOK_TIME_BASE + BEG_LOOK_TIME_ROLL,
            "the band the 40 + nextInt(40) keeps: {}",
            wolf.beg_look_time
        );
        // THE START'S OWN HEAD (start() the look never sets — the
        // tick's setLookAt the next GoalSelector walk serves)
        assert_eq!(wolf.head_yaw_off, 0.0, "the start the head never turns");
        // THE TICK (the setLookAt(player, 10.0F, getMaxHeadXRot()) the
        // head's own walk serves): the east player the -75 clamp wears
        // (the yaw offset the look_at law keeps), the taller eye the
        // pitch looks up
        let armed = wolf.beg_look_time;
        let _ = wolf.tick(&world, Some(&pv), NOON);
        assert!(wolf.interested, "the clock the continue keeps");
        assert_eq!(wolf.beg_look_time, armed - 1, "the --lookTime the tick walks");
        assert_eq!(wolf.head_yaw_off, -75.0, "the east stare the clamp wears");
        assert!(wolf.head_pitch < 0.0, "the taller eye the pitch looks up");
        // THE SWAP-AWAY (the interesting hand the re-read loses — the
        // stop law the flag drops, the clock zeroes)
        pv.held_item_id = None;
        let _ = wolf.tick(&world, Some(&pv), NOON);
        assert!(!wolf.interested, "the empty hand the stop speaks");
        assert_eq!(wolf.beg_look_time, 0, "the stop's own law the zero keeps");
        // THE RE-ARM (the bone's return the canUse re-answers — the
        // goal's own cycle the gate's own truth re-opens)
        pv.held_item_id = Some(bone_id);
        let _ = wolf.tick(&world, Some(&pv), NOON);
        assert!(wolf.interested, "the bone's return the beg re-arms");
    }

    /// THE BEGGOAL'S OWN GATES (the range the 64 square keeps, the LOS
