        // THE WALL (the checkLineOfSight default the sensing walk arms
        // — the stone column the ray walks into)
        let mut walled = flat_world();
        walled.set(10, 5, 8, crate::world::STONE);
        walled.set(10, 6, 8, crate::world::STONE);
