        // THE DEAD PLAYER (the isAlive gate the canUse walk keeps)
        let mut quiet = Zombie::new(4, 8.0, 5.0, 8.0, 4);
        quiet.kind = MobKind::Wolf;
        let mut dead = player_at(11.0, 5.0, 8.0);
        dead.held_item_id = Some(bone_id);
